window.L5R_CHARACTER = {"slug":"tsume-kunimichi","name":"Tsume Kunimichi","clan":"Crane","family":"Tsume","school":"Daidoji Harrier School","role":"Shinobi","bucket":"Shinobi","campaign":"The Bushi Oni","accent":"#83cecc","portrait":"src/portraits/tsume-kunimichi.png","concept":null,"summary":null,"tier_count":4,"xp_min":0,"xp_max":92,"twenty_questions":{"template":"core","generated":true,"steps":{"step1":{"answers":{"clan":"Crane","ring":"air","skill":"culture","social_status":35},"picks":{}},"step2":{"answers":{"family":"Tsume","ring":"water","skill1":"courtesy","skill2":"design","wealth":8,"social_glory":44},"picks":{}},"step3":{"answers":{"school":"Daidoji Harrier School","roles":"Shinobi","ring1":"air","ring2":"fire","skill1":"fitness","skill2":"skulduggery","skill3":"melee","skill4":"ranged","skill5":"medicine","social_honor":30},"picks":{"techniques":["Skulk","Striking as Air"],"school_ability":["Explosive Arrival"],"equipment":["Traveling pack","Traveling Clothes","Common Clothes","Katana","Knife","Wakizashi","Shuriken"]}},"step4":{"answers":{"stand_out":"Kunimichi has clear vision about what his capabilities and limitations are.","ring":"void"},"picks":{}},"step5":{"answers":{"social_giri":"Daidoji Masahiro, a regional administrator who oversees border territories and trade routes. Kunimichi's official duty is to serve as an advance scout and intelligence gatherer, traveling ahead of diplomatic missions to assess threats and gather information about local conditions. His reputation for thoroughness and discretion makes him invaluable for sensitive assignments where the Crane need eyes and ears in unfriendly territory."},"picks":{}},"step6":{"answers":{"social_ninjo":"To see the rigid hierarchy that keeps the common people suffering finally brought low. Kunimichi has witnessed too much injustice perpetuated by the celestial order - peasants starving while nobles feast, talented individuals held back by birth, and the Emperor's divine mandate used to justify cruelty. He longs for a world where merit and compassion matter more than bloodline and divine favor. This desire constantly puts him at odds with his official duties, as he must publicly support the very system he secretly works to undermine."},"picks":{}},"step7":{"answers":{"clan_relations":"Kunimichi genuinely respects the Daidoji family's values of hard work and practical service, but he's grown increasingly disillusioned with how the Crane's political maneuvering serves only the elite. He sees some of the Tsume and Daidoji good people trapped in a corrupt system, and his Kolat activities are partly motivated by a desire to free them from the endless cycle of serving the ungrateful Doji, and above them, Hantei XXXVIII. ","skill":"meditation","social_add_glory":0},"picks":{}},"step8":{"answers":{"bushido":"Kunimichi views Bushido as a beautiful philosophy corrupted by those in power. The ideals of Courage, Honor, and Compassion resonate with him deeply, but he's seen how Duty and Loyalty are weaponized to keep people obedient to unjust rulers. He believes true honor lies in serving the greater good of all people, not blindly following orders from divine autocrats. ","social_add_honor":10,"tenet_paramount":"Righteousness","tenet_less_significant":"Duty and Loyalty"},"picks":{}},"step9":{"answers":{"success":"Using carefully placed explosive charges to sink a trading vessel which was carrying a shipment of weapons intended for a Lion clan vassal who was becoming too powerful for Crane political interests. Kunimichi posed as a dock worker, and on the night before departure, he placed small but precisely calculated charges that went off more than a day later, while the ship was en route, sinking it."},"picks":{"distinction":["Famously Reliable"]}},"step10":{"answers":{"difficulty":"While learning to craft more sophisticated charges, an experimental mixture detonated prematurely, leaving his arm permanently weakened and scarred. Though he's adapted his techniques and become much more careful, the injury serves as a constant reminder of the dangers in his work. The physical limitation affects his ability to use certain weapons and perform some manual tasks, forcing him to rely more on precision and planning than raw capability."},"picks":{"adversity":["Maimed Arm"]}},"step11":{"answers":{"calms":"Kunimichi finds deep satisfaction in taking something that appears ruined and transforming it into something more beautiful than before. The careful, meditative process of examining cracks, mixing the precious metal, and slowly rebuilding broken pieces mirrors his hopes for society itself."},"picks":{"passion":["Kintsugi"]}},"step12":{"answers":{"worries":"Hypervigilance about being discovered by authorities or enemy agents. Kunimichi constantly scans crowds for familiar faces, analyzes every interaction for signs of suspicion, and maintains multiple exit strategies from any location. This paranoid awareness has saved his life several times, but it also exhausts him mentally and makes it difficult to form genuine relationships."},"picks":{"anxiety":["Eyes of Many"]}},"step13":{"answers":{"most_learn":"Yuki, a geisha who operates in the entertainment districts of Otosan Uchi. On the surface, she appears to be merely an accomplished entertainer skilled in poetry, music, and conversation. However, she is actually a high-ranking Kolat agent who first introduced Kunimichi to the conspiracy's philosophy during what appeared to be routine visits to a tea house. Through seemingly casual conversations about poetry and philosophy, she taught him to see the inherent contradictions in the Celestial Order and showed him how the rigid hierarchy perpetuates suffering. Her lessons in reading people, managing multiple identities, and maintaining perfect composure under pressure have been invaluable to his survival as a double agent. To any observer, their relationship appears to be that of a samurai seeking cultured entertainment, making it the perfect cover for their true mentorship.","skill":"performance"},"picks":{"disadvantage":["Bitter Betrothal"]}},"step14":{"answers":{"first_sight":"The careful way he holds his left arm - not protectively, but with a stiffness that suggests old injury. Those observant enough notice that he unconsciously favors his right side when reaching for items or gesturing. The scarring is mostly hidden by his clothing. Some interpret this as the mark of a dedicated warrior who has seen real action, which actually enhances his reputation for experience."},"picks":{"special_features":["Engineer's Kit"]}},"step15":{"answers":{"stress":"Kunimichi becomes eerily calm and methodical when under pressure. Years of managing explosives and maintaining his cover identity have taught him that panic leads to fatal mistakes. He speaks more quietly, moves more deliberately, and his eyes become constantly mobile as he assesses threats and escape routes. To most observers, this controlled response makes him appear calm, though those who know him well recognize it as a sign that he's operating in 'mission mode' and may be preparing for violence."},"picks":{}},"step16":{"answers":{"relations":"His marriage to Sodona Akemi is a constant source of tension in his life. Arranged to strengthen ties between the Crane and a Phoenix vassal family, their union is politically useful but personally hollow. Akemi is intelligent and dutiful but finds Kunimichi's frequent absences and emotional distance frustrating. She suspects he's hiding something but attributes it to typical masculine stoicism rather than his true secret. Their shared home is polite but cold, and both maintain their duties while privately resenting the arrangement.\n\nAdditionally, he maintains a professional relationship with Yasuki Toshiro, a Crab merchant who occasionally supplies the Crane with specialty goods. Unknown to most, Toshiro is actually a Kolat sympathizer who provides Kunimichi with hard-to-acquire materials for his sabotage work, disguised as legitimate trade goods. Toshiro gave him a carved jade medallion that identifies the bearer as someone he will do business with, no questions asked. Can be used to acquire unusual materials or arrange discreet meetings."},"picks":{}},"step17":{"answers":{"parents_pov":"His parents, Tsume Jiro and Tsume Mariko, would describe Kunimichi as 'their dutiful but distant son.' They're immensely proud of his reputation for completing difficult assignments and his marriage to a Phoenix family, seeing both as bringing honor to the Tsume name.  His father respects his dedication to duty but privately wishes Kunimichi would request safer assignments and focus on building a proper family with his wife. They see him as someone who gives everything to his obligations but takes little joy from life, though they assume this is simply the burden of serving the clan in dangerous times.","skill":"unarmed"},"picks":{}},"step18":{"answers":{"heritage_name":"He is named after his ancestor that was the most recent known link to the Imperial family.","heritage_1":9,"heritage_2":3,"heritage_add_honor":0,"heritage_add_glory":0,"heritage_add_status":10,"skill":"smithing"},"picks":{}},"step19":{"answers":{"firstname":"Kunimichi"},"picks":{}},"step20":{"answers":{"death":"Kunimichi is not under any illusions. Most likely, he dies by his own hand in an accident; next most likely is that the conspiracy is betrayed and he is executed."},"picks":{}}}},"notes":"","curriculum":[{"rank":1,"kind":"Skill Group","group":null,"label":"Trade Skills","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Fitness","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Martial Arts [Melee]","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Martial Arts [Ranged]","prereq":false},{"rank":1,"kind":"Tech. Grp.","group":"kata","label":"Rank 1 Kata","prereq":false},{"rank":1,"kind":"Technique","group":"shuji","label":"Clouds Parted by Steel","prereq":true},{"rank":1,"kind":"Technique","group":"ninjutsu","label":"Swift Scouting","prereq":true},{"rank":2,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Government","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Medicine","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Skulduggery","prereq":false},{"rank":2,"kind":"Tech. Grp.","group":"kata","label":"Rank 1-2 Kata","prereq":false},{"rank":2,"kind":"Technique","group":"ninjutsu","label":"The Patient Viper","prereq":true},{"rank":2,"kind":"Technique","group":"ninjutsu","label":"Employ Terrible Thunder","prereq":true},{"rank":3,"kind":"Skill Group","group":null,"label":"Scholar Skills","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Labor","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Martial Arts [Melee]","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Tactics","prereq":false},{"rank":3,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1-3 Air Shuji","prereq":false},{"rank":3,"kind":"Technique","group":"ritual","label":"Imbue Thunder","prereq":true},{"rank":3,"kind":"Technique","group":"ninjutsu","label":"Vanish in the Shadows","prereq":true},{"rank":4,"kind":"Skill Group","group":null,"label":"Trade Skills","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Martial Arts [Ranged]","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Medicine","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Sentiment","prereq":false},{"rank":4,"kind":"Tech. Grp.","group":"kata","label":"Rank 1-4 Kata","prereq":false},{"rank":4,"kind":"Technique","group":"ninjutsu","label":"Wreak Havoc","prereq":true},{"rank":4,"kind":"Technique","group":"ritual","label":"Beseech Bayushi's Absolution","prereq":false},{"rank":5,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Courtesy","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Medicine","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Survival","prereq":false},{"rank":5,"kind":"Tech. Grp.","group":"shuji","label":"Rank 1-5 Fire Shuji","prereq":false},{"rank":5,"kind":"Technique","group":"kata","label":"Pin the Fan","prereq":false},{"rank":5,"kind":"Technique","group":"ninjutsu","label":"Silencing Stroke","prereq":true}],"tiers":[{"xp":0,"label":null,"rank":1,"school":"Daidoji Harrier School","foundry_id":"X6mcVfFgcs8OzILh","rings":{"air":3,"earth":1,"fire":2,"water":2,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":0,"design":1,"smithing":1},"martial":{"fitness":1,"melee":1,"ranged":1,"unarmed":1,"meditation":1,"tactics":0},"scholar":{"culture":1,"government":0,"medicine":1,"sentiment":0,"theology":0},"social":{"command":0,"courtesy":1,"games":0,"performance":1},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":1,"survival":0}},"social":{"honor":40,"glory":44,"status":45,"ninjo":"To see the rigid hierarchy that keeps the common people suffering finally brought low. Kunimichi has witnessed too much injustice perpetuated by the celestial order - peasants starving while nobles feast, talented individuals held back by birth, and the Emperor's divine mandate used to justify cruelty. He longs for a world where merit and compassion matter more than bloodline and divine favor. This desire constantly puts him at odds with his official duties, as he must publicly support the very system he secretly works to undermine.","giri":"Daidoji Masahiro, a regional administrator who oversees border territories and trade routes. Kunimichi's official duty is to serve as an advance scout and intelligence gatherer, traveling ahead of diplomatic missions to assess threats and gather information about local conditions. His reputation for thoroughness and discretion makes him invaluable for sensitive assignments where the Crane need eyes and ears in unfriendly territory.","bushido_tenets":{"paramount":"Righteousness","less_significant":"Duty and Loyalty"}},"derived":{"endurance":6,"composure":6,"focus":5,"vigilance":3,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[],"techniques":[{"name":"Skulk","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ninjutsu","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Shinobi are known for walking silently from shadow to shadow, moving like phantoms. Some of this relies upon agility and speed, of course, but veterans in the art of stealth know that using a crowd or another visual distraction to walk unnoticed can be as effective as the most complex acrobatics.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform an Initiative or Attack check using Air, you may spend (op) as follows:</span></p><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If you are in Obscuring terrain, a crowd, or otherwise concealed from sight, one character with vigilance lower than or equal to your ranks in Skulduggery loses sight of you.</span></p>","source":{"book":"core_rulebook","page":226},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.tKw2dMxzwVBuWOaT"},{"name":"Striking as Air","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Not every stroke a warrior throws in battle is intended to kill—even if they all lead to that end goal. A skilled fighter can tell when an attack will not land and subtly shift it into a different sort of attack, meant to probe the enemy’s defenses or draw their guard out of position. By carefully placing attack after attack, a master of the blade can eventually whittle down their opponent’s options until none remain but death.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (Air) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(air)(op)+: </span><span class=\"fontstyle3\">Reserve one of your rolled dice, plus one additional die per (op)(op) spent this way. These dice become dropped dice. When making a check with the same skill before the end of your next turn, you may roll one fewer (ring) per reserved (ring) and one fewer (skill) per reserved (skill), then add the reserved dice to your roll. These dice count as rolled dice, but are added set to the results they had when they were reserved.</span></p>","source":{"book":"core_rulebook","page":177},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.pNvLI7ImoPeZPzwK"},{"name":"Explosive Arrival","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">After you perform an Attack action against a target who is Dazed or unaware of your presence, that target receives strife equal to your school rank. If your target is an enemy leader’s cohort in a mass battle, the enemy army also receives that much panic</span>.</p>","source":{"book":"fields_of_victory","page":74},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.bCg2D67yA5yoON9g"}],"peculiarities":[{"name":"Famously Reliable","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"earth","types":"Fame, Interpersonal","description":"<p><span class=\"fontstyle0\"><em>When the lord came to see how the smith was proceeding on his sword, he found the smithy a shambles, the river running through the forge, and the smith with his robes tied up around his middle.</em></span></p><p><span class=\"fontstyle0\"><em>“Tsi-san,” said the great lord. “I trust my sword will be ready tomorrow, as we agreed?”</em></span></p><p><span class=\"fontstyle0\"><em>“Of course, great lord,” said the smith, bowing low. “This is only a minor setback.”</em></span></p><p><span class=\"fontstyle2\"><em>– The Trials of Tsi Wenfu, </em></span><span class=\"fontstyle3\"><em>author unknown</em></span></p><p></p><p><span class=\"fontstyle2\">The following apply to a character with the Famously Reliable distinction:</span></p><ul><li><p><span class=\"fontstyle2\">- Other people have heard of you for your remarkable adherence to your oaths and responsibilities, even over and above most samurai, and they believe it by default unless given evidence to the contrary.</span></p></li><li><p><span class=\"fontstyle2\">- When performing a check for which you need to leverage your reputation for keeping your oaths and bargains (such as a Command (earth) check to calm a panicked soldier or a Performance (earth) check to relate a tale that inspires patience), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":104},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.DWrZtBuyK83Ah3a7"},{"name":"Maimed Arm","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"fire","types":"Physical, Scar","description":"<p><em>The samurai kept her arm tucked in her kimono. Her left sleeve flapped empty in the breeze, a testament to her folly—and resilience.</em></p><p></p><p>The following apply to a character with the Maimed Arm adversity:</p><ul><li><p>- Your right or left arm is injured (your choice at the time the disadvantage is assigned), making it much harder to perform activities that involve use of that arm. You can use the arm, but gripping anything tightly causes you pain, and you might need a sling to help the arm heal properly.</p></li><li><p>-  When you make a check for which you need to use two hands at once (such as a Design (fire) check to sew a new kimono or a Martial Arts (melee) (fire) check to overwhelm a foe with a powerful overhead slice), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":125},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.BUdmYV82FFppmXo1"},{"name":"Kintsugi","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"earth","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>Mirumoto Kinshichirō did not cry then. As a child, he carelessly dropped this bowl, one that had been in his family for generations, a gift supposedly blessed by the actual Kami Togashi. His parents berated him, and he carried the guilt all throughout his adolescence. He even decided to study with the Agasha mystics, but his parents cared so little, they let him leave.</em></span></p><p><span class=\"fontstyle0\"><em>They did not realize that hidden in his belongings, a box contained the pieces of the bowl, carefully wrapped in a cloth. This box remined by his side as he studied, until Kinshichirō had to make his masterpiece. The bowl had broken into seven pieces, exactly the number of his siblings plus him, yet when he unfolded the cloth, he noted he only had six. The despair he felt only lasted for a little while.</em></span></p><p><span class=\"fontstyle0\"><em>When Kinshichirō returned home, he unveiled the bowl. He had joined the cracks with gold, and the missing space filled with a singular piece of jade with the family mon. His siblings welcomed him back, so he finally allowed the tears to flow.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Kintsugi passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You have a particular fondness and skill for kintsugi, the art of mending broken pottery with gold or other similar substances.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to mend an object with kintsugi or interact with a piece of kintsugi-repaired pottery (such as a Culture (earth) check to recall the name of a particular practitioner of kintsugi by their artist’s mark on a piece of pottery or a Labor (earth) check to produce a breathtaking piece), you remove 3 strife.</span></p></li></ul>","source":{"book":"writ_of_the_wild","page":104},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.pVo3SUK4ZeNQUwye"},{"name":"Eyes of Many","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"air","types":"Mental","description":"<p><em>“If you live worrying about the eyes and thoughts of others, your life is no longer your own.”</em></p><p><em>– Youta, Mystic of the Mountain</em></p><p><strong>Effects:</strong> The following apply to a character with the Eyes of Many anxiety:</p><ul><li><p>-  You are constantly worried that others are watching and judging you, whether maliciously or not. You are unable to relax in crowded places, and you tend to worry about your impressions on strangers more than most other people would.</p></li><li><p>- After performing a check in a crowded place or where two or more strangers are actively listening to you (such as a Courtesy (air) check to tell your employer your mission went very well when it did not in front of their other retainers or a Fitness (air) check to avoid notice), you suffer 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":73},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.Sw9LFYlxdkwGFCfu"},{"name":"Bitter Betrothal","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Interpersonal","description":"<p><em>“My husband returns home tonight,” she said in a low whisper, passing the bag of coins beneath the table to the men seated across from her. Nobody in this inn knew her face, yet she still felt the need for caution. </em></p><p><em>“He will be traveling via the eastern road.”</em></p><p><em>“It shall be done,” said the leader. Without further word, he and his companions rose from the table and left the inn. The room seemed somehow lighter without them in it. Soon, she would be rid of him.</em></p><p></p><p>The following apply to a character with the Bitter Betrothal adversity</p><ul><li><p>- Something significantly complicates your relationship with your betrothed or spouse. As a result, they often undermine your efforts, whether out of malice, negligence, or an incompatible set of goals.</p></li><li><p>- When you make a check that requires the collaboration of your betrothed or spouse (such as a Courtesy (water) check to make a polite request to their family for political backing or a Culture (water) check to know the proper thing to do at a social function involving their relatives), you must choose and reroll two dice containing (su) or (ex). After resolving the check, if you failed, you gain 1 Void point.</p></li></ul><p></p>","source":{"book":"core_rulebook","page":117},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.p1cGWR2i5WrGtIKb"}],"titles":[],"bonds":[],"gear":[{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Shuriken","quantity":6,"description":"<p><span class=\"fontstyle0\">Favored by shinobi, shuriken are small metal discs with a sharpened edge that come in a dizzying array of sizes and styles. They are designed mainly to distract, but shuriken can also be coated with toxins for lethality, and any cutting edge can kill if used properly.</span></p>","source":{"book":"core_rulebook","page":237},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.5Lr1CNs1uvX7J38y","damage":2,"deadliness":4,"range":"0","grip_1":"(stab or slash): -, (thrown): Martial Arts [Ranged], Range 1-3","grip_2":"N/A","skill":"unarmed","category":"Specialist Weapons","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Common Clothes","quantity":1,"description":"<p>Rokugani clothing runs the gamut from the simple trousers and smocks worn by peasants, to the broad-shouldered haori worn by traditionalist samurai, to the noble’s embroidered silk kimono.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.vYOT19tl8uiIDt14","armor":{"physical":1,"supernatural":0},"rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Engineer's Kit","quantity":1,"description":"<p>These kits provide an architect, civil engineer, siege engineer, or builder with a set of basic tools for surveying and building. These tool kits typically include measuring and surveying tools, rolls of parchment for making plans, various drafting implements, and an assortment of carpenters’ and masons’ tools. (Cost: 3 bu. Rarity: 3.)</p>","source":{"book":"shadowlands","page":107},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.xFAWMoykfSYWIScE","rarity":"3","zeni":"3 bu"},{"name":"Jade Medallion","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"4","zeni":"0","properties":[]}]},{"xp":20,"label":"Rank 2","rank":2,"school":"Daidoji Harrier School","foundry_id":"ZZ1PguzJan2hK0u0","rings":{"air":3,"earth":1,"fire":2,"water":2,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":0,"design":1,"smithing":1},"martial":{"fitness":2,"melee":1,"ranged":2,"unarmed":1,"meditation":1,"tactics":0},"scholar":{"culture":1,"government":0,"medicine":1,"sentiment":0,"theology":0},"social":{"command":0,"courtesy":1,"games":0,"performance":1},"trade":{"commerce":1,"labor":0,"seafaring":1,"skulduggery":1,"survival":0}},"social":{"honor":40,"glory":44,"status":45,"ninjo":"To see the rigid hierarchy that keeps the common people suffering finally brought low. Kunimichi has witnessed too much injustice perpetuated by the celestial order - peasants starving while nobles feast, talented individuals held back by birth, and the Emperor's divine mandate used to justify cruelty. He longs for a world where merit and compassion matter more than bloodline and divine favor. This desire constantly puts him at odds with his official duties, as he must publicly support the very system he secretly works to undermine.","giri":"Daidoji Masahiro, a regional administrator who oversees border territories and trade routes. Kunimichi's official duty is to serve as an advance scout and intelligence gatherer, traveling ahead of diplomatic missions to assess threats and gather information about local conditions. His reputation for thoroughness and discretion makes him invaluable for sensitive assignments where the Crane need eyes and ears in unfriendly territory.","bushido_tenets":{"paramount":"Righteousness","less_significant":"Duty and Loyalty"}},"derived":{"endurance":6,"composure":6,"focus":5,"vigilance":3,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Commerce +1 (0 -> 1)","type":"skill","skill":"commerce","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Seafaring +1 (0 -> 1)","type":"skill","skill":"seafaring","ring":"void","at_rank":1,"xp":2,"in_curriculum":false},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Fitness +1 (1 -> 2)","type":"skill","skill":"fitness","ring":"void","at_rank":1,"xp":4,"in_curriculum":true}],"techniques":[{"name":"Skulk","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ninjutsu","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Shinobi are known for walking silently from shadow to shadow, moving like phantoms. Some of this relies upon agility and speed, of course, but veterans in the art of stealth know that using a crowd or another visual distraction to walk unnoticed can be as effective as the most complex acrobatics.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform an Initiative or Attack check using Air, you may spend (op) as follows:</span></p><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If you are in Obscuring terrain, a crowd, or otherwise concealed from sight, one character with vigilance lower than or equal to your ranks in Skulduggery loses sight of you.</span></p>","source":{"book":"core_rulebook","page":226},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.tKw2dMxzwVBuWOaT"},{"name":"Striking as Air","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Not every stroke a warrior throws in battle is intended to kill—even if they all lead to that end goal. A skilled fighter can tell when an attack will not land and subtly shift it into a different sort of attack, meant to probe the enemy’s defenses or draw their guard out of position. By carefully placing attack after attack, a master of the blade can eventually whittle down their opponent’s options until none remain but death.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (Air) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(air)(op)+: </span><span class=\"fontstyle3\">Reserve one of your rolled dice, plus one additional die per (op)(op) spent this way. These dice become dropped dice. When making a check with the same skill before the end of your next turn, you may roll one fewer (ring) per reserved (ring) and one fewer (skill) per reserved (skill), then add the reserved dice to your roll. These dice count as rolled dice, but are added set to the results they had when they were reserved.</span></p>","source":{"book":"core_rulebook","page":177},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.pNvLI7ImoPeZPzwK"},{"name":"Explosive Arrival","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">After you perform an Attack action against a target who is Dazed or unaware of your presence, that target receives strife equal to your school rank. If your target is an enemy leader’s cohort in a mass battle, the enemy army also receives that much panic</span>.</p>","source":{"book":"fields_of_victory","page":74},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.bCg2D67yA5yoON9g"},{"name":"Swift Scouting","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ninjutsu","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The line between a shinobi and a scout is mostly one of their current assignment. Yet, while traditional scouting can take days or weeks, sufficiently experienced survivalists who have lived in the wilds can undertake scouting missions much more quickly than typical observers. Shinobi must often spend long periods of time traveling Rokugan, hiding in the wilderness, or spying on targets on the road. As a result, many are intimately familiar with the sorts of environments found in those types of locations and can quickly sweep an area to identify the points of interest inside it. Especially skilled shinobi are likely to leave traps behind for enemy scouts or forces in the area.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, or once per scene as a Movement and Support action, you may make a </span><span class=\"fontstyle2\">TN 3 Survival (water) check </span><span class=\"fontstyle3\">to scout the terrain around you. If you activate this technique in an urban environment or on the ocean, use Skulduggery or Seafaring instead, respectively.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you discover all terrain qualities of the area around you (several miles in all direction during downtime, or the entire area in which the scene is occurring), as well as any fortifications in the area. Characters with vigilance lower than your Air Ring plus your bonus successes do not detect you during this time.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(water)(op)(op) </span><span class=\"fontstyle2\">(<em>Downtime</em> or <em>Mass Battle</em>): </span><span class=\"fontstyle3\">If you succeed, you may choose one part of the area (a single battle zone, if using the rules for battle zones) and add one of the following terrain qualities to that area: Confining, Dangerous, Entangling, Obscuring.</span></p><p><span class=\"fontstyle2\">(water)(op)(op) (<em>Other Scene</em>): </span><span class=\"fontstyle3\">If you succeed, you may choose a position in the area you scouted. Up to three range bands surrounding that position gain one of the following terrain qualities: Confining, Dangerous, Entangling, Obscuring.</span></p><p><span class=\"fontstyle5\">(water)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">You discover the location and composition of any enemy forces in the area led by characters with Air Ring lower than your vigilance plus (op) spent this way.</span></p><p><span class=\"fontstyle5\">(water)(op)(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">During your next turn, if you perform an action targeting an enemy cohort, ignore any fortification it is occupying. You may resolve effects as if you were inside that fortification.</span></p>","source":{"book":"fields_of_victory","page":105},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.JuuH6W9ZSSNnnyYq","skill":"survival"},{"name":"Trip the Leg","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The bushi’s spear flashes out, aiming low to trip up their opponent and send the unlucky foe crashing to the ground.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action using one readied polearm, you may make a </span><span class=\"fontstyle2\">TN 2 Martial Arts [Melee] check </span><span class=\"fontstyle3\">targeting one character at range 1–2.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Prone condition.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you succeed, the target receives 2 fatigue and 2 strife.</span></p><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">If your target’s vigilance is lower than or equal to </span><span class=\"fontstyle5\">(op) </span><span class=\"fontstyle3\">spent this way, they suffer the Disoriented condition.</span></p>","source":{"book":"court_of_stones","page":113},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.wJuo5wuCSga4kIc2","skill":"melee"},{"name":"Cautious Tread","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Horses and camels are excellent mounts, but their long legs make them somewhat more vulnerable to certain kinds of terrain than their human riders. A skillful handler knows how to lead their mount around the most dangerous spots, whether holes dug by rodents in the plains, swampy terrain, or chasms in the desert.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Movement action check while riding a mount, you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(op)(op): </span><span class=\"fontstyle3\">Choose one of the following terrain qualities: Dangerous, Entangling, or Obscuring. You and your mount ignore its effects. This effect persists until the end of your next turn.</span></p>","source":{"book":"children_of_the_five_winds","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.O8sn8QkmCqKqBe6G"}],"peculiarities":[{"name":"Famously Reliable","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"earth","types":"Fame, Interpersonal","description":"<p><span class=\"fontstyle0\"><em>When the lord came to see how the smith was proceeding on his sword, he found the smithy a shambles, the river running through the forge, and the smith with his robes tied up around his middle.</em></span></p><p><span class=\"fontstyle0\"><em>“Tsi-san,” said the great lord. “I trust my sword will be ready tomorrow, as we agreed?”</em></span></p><p><span class=\"fontstyle0\"><em>“Of course, great lord,” said the smith, bowing low. “This is only a minor setback.”</em></span></p><p><span class=\"fontstyle2\"><em>– The Trials of Tsi Wenfu, </em></span><span class=\"fontstyle3\"><em>author unknown</em></span></p><p></p><p><span class=\"fontstyle2\">The following apply to a character with the Famously Reliable distinction:</span></p><ul><li><p><span class=\"fontstyle2\">- Other people have heard of you for your remarkable adherence to your oaths and responsibilities, even over and above most samurai, and they believe it by default unless given evidence to the contrary.</span></p></li><li><p><span class=\"fontstyle2\">- When performing a check for which you need to leverage your reputation for keeping your oaths and bargains (such as a Command (earth) check to calm a panicked soldier or a Performance (earth) check to relate a tale that inspires patience), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":104},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.DWrZtBuyK83Ah3a7"},{"name":"Maimed Arm","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"fire","types":"Physical, Scar","description":"<p><em>The samurai kept her arm tucked in her kimono. Her left sleeve flapped empty in the breeze, a testament to her folly—and resilience.</em></p><p></p><p>The following apply to a character with the Maimed Arm adversity:</p><ul><li><p>- Your right or left arm is injured (your choice at the time the disadvantage is assigned), making it much harder to perform activities that involve use of that arm. You can use the arm, but gripping anything tightly causes you pain, and you might need a sling to help the arm heal properly.</p></li><li><p>-  When you make a check for which you need to use two hands at once (such as a Design (fire) check to sew a new kimono or a Martial Arts (melee) (fire) check to overwhelm a foe with a powerful overhead slice), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":125},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.BUdmYV82FFppmXo1"},{"name":"Kintsugi","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"earth","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>Mirumoto Kinshichirō did not cry then. As a child, he carelessly dropped this bowl, one that had been in his family for generations, a gift supposedly blessed by the actual Kami Togashi. His parents berated him, and he carried the guilt all throughout his adolescence. He even decided to study with the Agasha mystics, but his parents cared so little, they let him leave.</em></span></p><p><span class=\"fontstyle0\"><em>They did not realize that hidden in his belongings, a box contained the pieces of the bowl, carefully wrapped in a cloth. This box remined by his side as he studied, until Kinshichirō had to make his masterpiece. The bowl had broken into seven pieces, exactly the number of his siblings plus him, yet when he unfolded the cloth, he noted he only had six. The despair he felt only lasted for a little while.</em></span></p><p><span class=\"fontstyle0\"><em>When Kinshichirō returned home, he unveiled the bowl. He had joined the cracks with gold, and the missing space filled with a singular piece of jade with the family mon. His siblings welcomed him back, so he finally allowed the tears to flow.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Kintsugi passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You have a particular fondness and skill for kintsugi, the art of mending broken pottery with gold or other similar substances.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to mend an object with kintsugi or interact with a piece of kintsugi-repaired pottery (such as a Culture (earth) check to recall the name of a particular practitioner of kintsugi by their artist’s mark on a piece of pottery or a Labor (earth) check to produce a breathtaking piece), you remove 3 strife.</span></p></li></ul>","source":{"book":"writ_of_the_wild","page":104},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.pVo3SUK4ZeNQUwye"},{"name":"Eyes of Many","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"air","types":"Mental","description":"<p><em>“If you live worrying about the eyes and thoughts of others, your life is no longer your own.”</em></p><p><em>– Youta, Mystic of the Mountain</em></p><p><strong>Effects:</strong> The following apply to a character with the Eyes of Many anxiety:</p><ul><li><p>-  You are constantly worried that others are watching and judging you, whether maliciously or not. You are unable to relax in crowded places, and you tend to worry about your impressions on strangers more than most other people would.</p></li><li><p>- After performing a check in a crowded place or where two or more strangers are actively listening to you (such as a Courtesy (air) check to tell your employer your mission went very well when it did not in front of their other retainers or a Fitness (air) check to avoid notice), you suffer 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":73},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.Sw9LFYlxdkwGFCfu"},{"name":"Bitter Betrothal","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Interpersonal","description":"<p><em>“My husband returns home tonight,” she said in a low whisper, passing the bag of coins beneath the table to the men seated across from her. Nobody in this inn knew her face, yet she still felt the need for caution. </em></p><p><em>“He will be traveling via the eastern road.”</em></p><p><em>“It shall be done,” said the leader. Without further word, he and his companions rose from the table and left the inn. The room seemed somehow lighter without them in it. Soon, she would be rid of him.</em></p><p></p><p>The following apply to a character with the Bitter Betrothal adversity</p><ul><li><p>- Something significantly complicates your relationship with your betrothed or spouse. As a result, they often undermine your efforts, whether out of malice, negligence, or an incompatible set of goals.</p></li><li><p>- When you make a check that requires the collaboration of your betrothed or spouse (such as a Courtesy (water) check to make a polite request to their family for political backing or a Culture (water) check to know the proper thing to do at a social function involving their relatives), you must choose and reroll two dice containing (su) or (ex). After resolving the check, if you failed, you gain 1 Void point.</p></li></ul><p></p>","source":{"book":"core_rulebook","page":117},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.p1cGWR2i5WrGtIKb"}],"titles":[],"bonds":[],"gear":[{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Shuriken","quantity":6,"description":"<p><span class=\"fontstyle0\">Favored by shinobi, shuriken are small metal discs with a sharpened edge that come in a dizzying array of sizes and styles. They are designed mainly to distract, but shuriken can also be coated with toxins for lethality, and any cutting edge can kill if used properly.</span></p>","source":{"book":"core_rulebook","page":237},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.5Lr1CNs1uvX7J38y","damage":2,"deadliness":4,"range":"0","grip_1":"(stab or slash): -, (thrown): Martial Arts [Ranged], Range 1-3","grip_2":"N/A","skill":"unarmed","category":"Specialist Weapons","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Common Clothes","quantity":1,"description":"<p>Rokugani clothing runs the gamut from the simple trousers and smocks worn by peasants, to the broad-shouldered haori worn by traditionalist samurai, to the noble’s embroidered silk kimono.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.vYOT19tl8uiIDt14","armor":{"physical":1,"supernatural":0},"rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Engineer's Kit","quantity":1,"description":"<p>These kits provide an architect, civil engineer, siege engineer, or builder with a set of basic tools for surveying and building. These tool kits typically include measuring and surveying tools, rolls of parchment for making plans, various drafting implements, and an assortment of carpenters’ and masons’ tools. (Cost: 3 bu. Rarity: 3.)</p>","source":{"book":"shadowlands","page":107},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.xFAWMoykfSYWIScE","rarity":"3","zeni":"3 bu"},{"name":"Jade Medallion","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"4","zeni":"0","properties":[]}]},{"xp":49,"label":"Rank 3","rank":3,"school":"Daidoji Harrier School","foundry_id":"mk4X2a3CKwKeFJbs","rings":{"air":3,"earth":1,"fire":2,"water":2,"void":3},"skills":{"artisan":{"aesthetics":0,"composition":0,"design":1,"smithing":1},"martial":{"fitness":2,"melee":1,"ranged":3,"unarmed":1,"meditation":1,"tactics":0},"scholar":{"culture":1,"government":0,"medicine":1,"sentiment":0,"theology":0},"social":{"command":0,"courtesy":1,"games":0,"performance":1},"trade":{"commerce":1,"labor":0,"seafaring":1,"skulduggery":2,"survival":0}},"social":{"honor":40,"glory":44,"status":45,"ninjo":"To see the rigid hierarchy that keeps the common people suffering finally brought low. Kunimichi has witnessed too much injustice perpetuated by the celestial order - peasants starving while nobles feast, talented individuals held back by birth, and the Emperor's divine mandate used to justify cruelty. He longs for a world where merit and compassion matter more than bloodline and divine favor. This desire constantly puts him at odds with his official duties, as he must publicly support the very system he secretly works to undermine.","giri":"Daidoji Masahiro, a regional administrator who oversees border territories and trade routes. Kunimichi's official duty is to serve as an advance scout and intelligence gatherer, traveling ahead of diplomatic missions to assess threats and gather information about local conditions. His reputation for thoroughness and discretion makes him invaluable for sensitive assignments where the Crane need eyes and ears in unfriendly territory.","bushido_tenets":{"paramount":"Righteousness","less_significant":"Duty and Loyalty"}},"derived":{"endurance":6,"composure":6,"focus":5,"vigilance":3,"void_points":3},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Commerce +1 (0 -> 1)","type":"skill","skill":"commerce","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Seafaring +1 (0 -> 1)","type":"skill","skill":"seafaring","ring":"void","at_rank":1,"xp":2,"in_curriculum":false},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Fitness +1 (1 -> 2)","type":"skill","skill":"fitness","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Void +1 (2 -> 3)","type":"ring","skill":null,"ring":"void","at_rank":2,"xp":9,"in_curriculum":false},{"label":"Skulduggery +1 (1 -> 2)","type":"skill","skill":"skulduggery","ring":"void","at_rank":2,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (2 -> 3)","type":"skill","skill":"ranged","ring":"void","at_rank":2,"xp":6,"in_curriculum":true}],"techniques":[{"name":"Skulk","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ninjutsu","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Shinobi are known for walking silently from shadow to shadow, moving like phantoms. Some of this relies upon agility and speed, of course, but veterans in the art of stealth know that using a crowd or another visual distraction to walk unnoticed can be as effective as the most complex acrobatics.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform an Initiative or Attack check using Air, you may spend (op) as follows:</span></p><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If you are in Obscuring terrain, a crowd, or otherwise concealed from sight, one character with vigilance lower than or equal to your ranks in Skulduggery loses sight of you.</span></p>","source":{"book":"core_rulebook","page":226},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.tKw2dMxzwVBuWOaT"},{"name":"Striking as Air","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Not every stroke a warrior throws in battle is intended to kill—even if they all lead to that end goal. A skilled fighter can tell when an attack will not land and subtly shift it into a different sort of attack, meant to probe the enemy’s defenses or draw their guard out of position. By carefully placing attack after attack, a master of the blade can eventually whittle down their opponent’s options until none remain but death.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (Air) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(air)(op)+: </span><span class=\"fontstyle3\">Reserve one of your rolled dice, plus one additional die per (op)(op) spent this way. These dice become dropped dice. When making a check with the same skill before the end of your next turn, you may roll one fewer (ring) per reserved (ring) and one fewer (skill) per reserved (skill), then add the reserved dice to your roll. These dice count as rolled dice, but are added set to the results they had when they were reserved.</span></p>","source":{"book":"core_rulebook","page":177},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.pNvLI7ImoPeZPzwK"},{"name":"Explosive Arrival","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">After you perform an Attack action against a target who is Dazed or unaware of your presence, that target receives strife equal to your school rank. If your target is an enemy leader’s cohort in a mass battle, the enemy army also receives that much panic</span>.</p>","source":{"book":"fields_of_victory","page":74},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.bCg2D67yA5yoON9g"},{"name":"Swift Scouting","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ninjutsu","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The line between a shinobi and a scout is mostly one of their current assignment. Yet, while traditional scouting can take days or weeks, sufficiently experienced survivalists who have lived in the wilds can undertake scouting missions much more quickly than typical observers. Shinobi must often spend long periods of time traveling Rokugan, hiding in the wilderness, or spying on targets on the road. As a result, many are intimately familiar with the sorts of environments found in those types of locations and can quickly sweep an area to identify the points of interest inside it. Especially skilled shinobi are likely to leave traps behind for enemy scouts or forces in the area.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, or once per scene as a Movement and Support action, you may make a </span><span class=\"fontstyle2\">TN 3 Survival (water) check </span><span class=\"fontstyle3\">to scout the terrain around you. If you activate this technique in an urban environment or on the ocean, use Skulduggery or Seafaring instead, respectively.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you discover all terrain qualities of the area around you (several miles in all direction during downtime, or the entire area in which the scene is occurring), as well as any fortifications in the area. Characters with vigilance lower than your Air Ring plus your bonus successes do not detect you during this time.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(water)(op)(op) </span><span class=\"fontstyle2\">(<em>Downtime</em> or <em>Mass Battle</em>): </span><span class=\"fontstyle3\">If you succeed, you may choose one part of the area (a single battle zone, if using the rules for battle zones) and add one of the following terrain qualities to that area: Confining, Dangerous, Entangling, Obscuring.</span></p><p><span class=\"fontstyle2\">(water)(op)(op) (<em>Other Scene</em>): </span><span class=\"fontstyle3\">If you succeed, you may choose a position in the area you scouted. Up to three range bands surrounding that position gain one of the following terrain qualities: Confining, Dangerous, Entangling, Obscuring.</span></p><p><span class=\"fontstyle5\">(water)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">You discover the location and composition of any enemy forces in the area led by characters with Air Ring lower than your vigilance plus (op) spent this way.</span></p><p><span class=\"fontstyle5\">(water)(op)(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">During your next turn, if you perform an action targeting an enemy cohort, ignore any fortification it is occupying. You may resolve effects as if you were inside that fortification.</span></p>","source":{"book":"fields_of_victory","page":105},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.JuuH6W9ZSSNnnyYq","skill":"survival"},{"name":"Trip the Leg","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The bushi’s spear flashes out, aiming low to trip up their opponent and send the unlucky foe crashing to the ground.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action using one readied polearm, you may make a </span><span class=\"fontstyle2\">TN 2 Martial Arts [Melee] check </span><span class=\"fontstyle3\">targeting one character at range 1–2.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Prone condition.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you succeed, the target receives 2 fatigue and 2 strife.</span></p><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">If your target’s vigilance is lower than or equal to </span><span class=\"fontstyle5\">(op) </span><span class=\"fontstyle3\">spent this way, they suffer the Disoriented condition.</span></p>","source":{"book":"court_of_stones","page":113},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.wJuo5wuCSga4kIc2","skill":"melee"},{"name":"Cautious Tread","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Horses and camels are excellent mounts, but their long legs make them somewhat more vulnerable to certain kinds of terrain than their human riders. A skillful handler knows how to lead their mount around the most dangerous spots, whether holes dug by rodents in the plains, swampy terrain, or chasms in the desert.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Movement action check while riding a mount, you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(op)(op): </span><span class=\"fontstyle3\">Choose one of the following terrain qualities: Dangerous, Entangling, or Obscuring. You and your mount ignore its effects. This effect persists until the end of your next turn.</span></p>","source":{"book":"children_of_the_five_winds","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.O8sn8QkmCqKqBe6G"},{"name":"Employ Terrible Thunder","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"ninjutsu","rank":2,"description":"<p><span class=\"fontstyle0\"><em>For some samurai, there is something they prize above honor: victory. For them, honor is meaningless if their lord is dead or their family lost. Any method that achieves victory is worthy, even if the Emperor themselves has outlawed it.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Movement and Support action, you may make a </span><span class=\"fontstyle2\">TN 4 Skulduggery check </span><span class=\"fontstyle3\">and expend 1 charge of blasting powder (see page 90) to place it in your environment at a target position at range 0–1 of you. You must forfeit honor equal to equal to half your honor rank (rounded up) to use this technique.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you set the blasting powder to explode at the end of the next round. Some or all of the following occur based on the scene type:</span></p><ul><li><p><span class=\"fontstyle3\">- (<em>Mass Battle</em>) Any nearby cohort (such as those in the same zone, if using the rules for zones on page 118) is caught by the blast, and that army receives 5 attrition and 5 panic, plus 1 per bonus success.</span></p></li><li><p><span class=\"fontstyle3\">- (<em>Mass Battle</em>) If you placed the blasting powder inside of a fortification (see the </span><span class=\"fontstyle2\">Fortifications </span><span class=\"fontstyle3\">sidebar on page 276 of the core rulebook), reduce its difficulty value by 1, plus 1 per bonus success.</span></p></li><li><p><span class=\"fontstyle3\">- (<em>Mass Battle</em>) One cohort leader affected by the explosion suffers the Immobilized and Lightly Wounded conditions.</span></p></li><li><p><span class=\"fontstyle3\">- (<em>Other Scene</em>) Each character at range 0–2 of the target position suffers 10 physical damage plus 1 per bonus success, suffers the Dazed condition, and receives 5 strife.</span></p></li><li><p><span class=\"fontstyle3\">- (<em>Other Scene</em>) Items at range 0–2 of the target position gain the Damaged item quality.</span></p></li><li><p><span class=\"fontstyle3\">- (<em>Other Scene</em>) Any structure (such as a bridge, house, or wall) at range 0–1 of the target position gains the Damaged quality.</span></p></li></ul><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle6\">(op)</span><span class=\"fontstyle2\" style=\"color:rgb(0,0,0);\">: </span><span class=\"fontstyle3\">Any item or structure damaged by this effect gains the Destroyed quality instead.</span></p><p><span class=\"fontstyle2\" style=\"color:rgb(0,0,0);\">(op)(op): </span><span class=\"fontstyle3\">The area at range 0–2 of the position of the explosion gains the Dangerous and Obscuring terrain qualities, and flammable objects in the area are set ablaze.</span></p><p><span class=\"fontstyle2\">(op)+: </span><span class=\"fontstyle3\">The blasting powder does not detonate for one additional round per (op) spent this way.</span></p>","source":{"book":"fields_of_victory","page":105},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.ek7B6RF2KoXowmIU","skill":"skulduggery"},{"name":"Staggering Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Putting an arrow at a foe’s feet can cause them to stumble or trip, and an experienced archer knows how to take full advantage of this, planting bolts to break an</em></span><em> </em><span class=\"fontstyle0\"><em>enemy’s stride or pinning their clothes to slow them down, making any approach extremely treacherous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Martial Arts [Ranged] check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (fire)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Dangerous quality. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(air) or (water)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Entangling quality. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.6N5n9fweaz1CbLCu"},{"name":"The Patient Viper","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"ninjutsu","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Sometimes, the best way to approach a target is to stand still. Shinobi often lie in wait for hours or even days, patiently maintaining their position to ensure that they strike well when their foe arrives.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, you may make a </span><span class=\"fontstyle2\">TN 4 Fitness (earth) check </span><span class=\"fontstyle3\">targeting your cohort </span><span class=\"fontstyle3\" style=\"color:rgb(0,0,0);\">(if you are currently the leader of a cohort) </span><span class=\"fontstyle3\">or yourself and a number of other characters up to your ranks in Command (in any other scene) who are within Dangerous, Entangling, or Obscuring terrain.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, all targets become hidden and are not noticed by characters with vigilance lower than or equal to your Earth Ring plus your bonus successes. These hidden characters cannot be the target of Attack actions. This effect persists until the end of your next turn, or until any target you have hidden performs an Attack or Movement action.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(earth)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">This effect persists for one additional round per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(earth)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Reduce the TN of the first Attack action check one of your targets makes against another character in the terrain in which your forces are hidden by 1 per (op) spent this way.</span></p>","source":{"book":"fields_of_victory","page":106},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.fjq7mXymhQT93tSi","skill":"fitness"}],"peculiarities":[{"name":"Famously Reliable","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"earth","types":"Fame, Interpersonal","description":"<p><span class=\"fontstyle0\"><em>When the lord came to see how the smith was proceeding on his sword, he found the smithy a shambles, the river running through the forge, and the smith with his robes tied up around his middle.</em></span></p><p><span class=\"fontstyle0\"><em>“Tsi-san,” said the great lord. “I trust my sword will be ready tomorrow, as we agreed?”</em></span></p><p><span class=\"fontstyle0\"><em>“Of course, great lord,” said the smith, bowing low. “This is only a minor setback.”</em></span></p><p><span class=\"fontstyle2\"><em>– The Trials of Tsi Wenfu, </em></span><span class=\"fontstyle3\"><em>author unknown</em></span></p><p></p><p><span class=\"fontstyle2\">The following apply to a character with the Famously Reliable distinction:</span></p><ul><li><p><span class=\"fontstyle2\">- Other people have heard of you for your remarkable adherence to your oaths and responsibilities, even over and above most samurai, and they believe it by default unless given evidence to the contrary.</span></p></li><li><p><span class=\"fontstyle2\">- When performing a check for which you need to leverage your reputation for keeping your oaths and bargains (such as a Command (earth) check to calm a panicked soldier or a Performance (earth) check to relate a tale that inspires patience), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":104},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.DWrZtBuyK83Ah3a7"},{"name":"Maimed Arm","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"fire","types":"Physical, Scar","description":"<p><em>The samurai kept her arm tucked in her kimono. Her left sleeve flapped empty in the breeze, a testament to her folly—and resilience.</em></p><p></p><p>The following apply to a character with the Maimed Arm adversity:</p><ul><li><p>- Your right or left arm is injured (your choice at the time the disadvantage is assigned), making it much harder to perform activities that involve use of that arm. You can use the arm, but gripping anything tightly causes you pain, and you might need a sling to help the arm heal properly.</p></li><li><p>-  When you make a check for which you need to use two hands at once (such as a Design (fire) check to sew a new kimono or a Martial Arts (melee) (fire) check to overwhelm a foe with a powerful overhead slice), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":125},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.BUdmYV82FFppmXo1"},{"name":"Kintsugi","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"earth","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>Mirumoto Kinshichirō did not cry then. As a child, he carelessly dropped this bowl, one that had been in his family for generations, a gift supposedly blessed by the actual Kami Togashi. His parents berated him, and he carried the guilt all throughout his adolescence. He even decided to study with the Agasha mystics, but his parents cared so little, they let him leave.</em></span></p><p><span class=\"fontstyle0\"><em>They did not realize that hidden in his belongings, a box contained the pieces of the bowl, carefully wrapped in a cloth. This box remined by his side as he studied, until Kinshichirō had to make his masterpiece. The bowl had broken into seven pieces, exactly the number of his siblings plus him, yet when he unfolded the cloth, he noted he only had six. The despair he felt only lasted for a little while.</em></span></p><p><span class=\"fontstyle0\"><em>When Kinshichirō returned home, he unveiled the bowl. He had joined the cracks with gold, and the missing space filled with a singular piece of jade with the family mon. His siblings welcomed him back, so he finally allowed the tears to flow.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Kintsugi passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You have a particular fondness and skill for kintsugi, the art of mending broken pottery with gold or other similar substances.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to mend an object with kintsugi or interact with a piece of kintsugi-repaired pottery (such as a Culture (earth) check to recall the name of a particular practitioner of kintsugi by their artist’s mark on a piece of pottery or a Labor (earth) check to produce a breathtaking piece), you remove 3 strife.</span></p></li></ul>","source":{"book":"writ_of_the_wild","page":104},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.pVo3SUK4ZeNQUwye"},{"name":"Eyes of Many","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"air","types":"Mental","description":"<p><em>“If you live worrying about the eyes and thoughts of others, your life is no longer your own.”</em></p><p><em>– Youta, Mystic of the Mountain</em></p><p><strong>Effects:</strong> The following apply to a character with the Eyes of Many anxiety:</p><ul><li><p>-  You are constantly worried that others are watching and judging you, whether maliciously or not. You are unable to relax in crowded places, and you tend to worry about your impressions on strangers more than most other people would.</p></li><li><p>- After performing a check in a crowded place or where two or more strangers are actively listening to you (such as a Courtesy (air) check to tell your employer your mission went very well when it did not in front of their other retainers or a Fitness (air) check to avoid notice), you suffer 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":73},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.Sw9LFYlxdkwGFCfu"},{"name":"Bitter Betrothal","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Interpersonal","description":"<p><em>“My husband returns home tonight,” she said in a low whisper, passing the bag of coins beneath the table to the men seated across from her. Nobody in this inn knew her face, yet she still felt the need for caution. </em></p><p><em>“He will be traveling via the eastern road.”</em></p><p><em>“It shall be done,” said the leader. Without further word, he and his companions rose from the table and left the inn. The room seemed somehow lighter without them in it. Soon, she would be rid of him.</em></p><p></p><p>The following apply to a character with the Bitter Betrothal adversity</p><ul><li><p>- Something significantly complicates your relationship with your betrothed or spouse. As a result, they often undermine your efforts, whether out of malice, negligence, or an incompatible set of goals.</p></li><li><p>- When you make a check that requires the collaboration of your betrothed or spouse (such as a Courtesy (water) check to make a polite request to their family for political backing or a Culture (water) check to know the proper thing to do at a social function involving their relatives), you must choose and reroll two dice containing (su) or (ex). After resolving the check, if you failed, you gain 1 Void point.</p></li></ul><p></p>","source":{"book":"core_rulebook","page":117},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.p1cGWR2i5WrGtIKb"}],"titles":[],"bonds":[],"gear":[{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Shuriken","quantity":6,"description":"<p><span class=\"fontstyle0\">Favored by shinobi, shuriken are small metal discs with a sharpened edge that come in a dizzying array of sizes and styles. They are designed mainly to distract, but shuriken can also be coated with toxins for lethality, and any cutting edge can kill if used properly.</span></p>","source":{"book":"core_rulebook","page":237},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.5Lr1CNs1uvX7J38y","damage":2,"deadliness":4,"range":"0","grip_1":"(stab or slash): -, (thrown): Martial Arts [Ranged], Range 1-3","grip_2":"N/A","skill":"unarmed","category":"Specialist Weapons","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Common Clothes","quantity":1,"description":"<p>Rokugani clothing runs the gamut from the simple trousers and smocks worn by peasants, to the broad-shouldered haori worn by traditionalist samurai, to the noble’s embroidered silk kimono.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.vYOT19tl8uiIDt14","armor":{"physical":1,"supernatural":0},"rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Engineer's Kit","quantity":1,"description":"<p>These kits provide an architect, civil engineer, siege engineer, or builder with a set of basic tools for surveying and building. These tool kits typically include measuring and surveying tools, rolls of parchment for making plans, various drafting implements, and an assortment of carpenters’ and masons’ tools. (Cost: 3 bu. Rarity: 3.)</p>","source":{"book":"shadowlands","page":107},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.xFAWMoykfSYWIScE","rarity":"3","zeni":"3 bu"},{"name":"Jade Medallion","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"4","zeni":"0","properties":[]}]},{"xp":92,"label":"Master Saboteur, Rank 3","rank":3,"school":"Daidoji Harrier School","foundry_id":"MuW0K9mF1N9oJfVy","rings":{"air":3,"earth":1,"fire":2,"water":2,"void":3},"skills":{"artisan":{"aesthetics":0,"composition":0,"design":1,"smithing":1},"martial":{"fitness":2,"melee":2,"ranged":3,"unarmed":3,"meditation":1,"tactics":0},"scholar":{"culture":1,"government":1,"medicine":3,"sentiment":0,"theology":0},"social":{"command":0,"courtesy":1,"games":0,"performance":1},"trade":{"commerce":1,"labor":1,"seafaring":1,"skulduggery":2,"survival":0}},"social":{"honor":40,"glory":44,"status":45,"ninjo":"To see the rigid hierarchy that keeps the common people suffering finally brought low. Kunimichi has witnessed too much injustice perpetuated by the celestial order - peasants starving while nobles feast, talented individuals held back by birth, and the Emperor's divine mandate used to justify cruelty. He longs for a world where merit and compassion matter more than bloodline and divine favor. This desire constantly puts him at odds with his official duties, as he must publicly support the very system he secretly works to undermine.","giri":"Daidoji Masahiro, a regional administrator who oversees border territories and trade routes. Kunimichi's official duty is to serve as an advance scout and intelligence gatherer, traveling ahead of diplomatic missions to assess threats and gather information about local conditions. His reputation for thoroughness and discretion makes him invaluable for sensitive assignments where the Crane need eyes and ears in unfriendly territory.","bushido_tenets":{"paramount":"Righteousness","less_significant":"Duty and Loyalty"}},"derived":{"endurance":6,"composure":6,"focus":5,"vigilance":3,"void_points":3},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Commerce +1 (0 -> 1)","type":"skill","skill":"commerce","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Seafaring +1 (0 -> 1)","type":"skill","skill":"seafaring","ring":"void","at_rank":1,"xp":2,"in_curriculum":false},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Fitness +1 (1 -> 2)","type":"skill","skill":"fitness","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Void +1 (2 -> 3)","type":"ring","skill":null,"ring":"void","at_rank":2,"xp":9,"in_curriculum":false},{"label":"Skulduggery +1 (1 -> 2)","type":"skill","skill":"skulduggery","ring":"void","at_rank":2,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (2 -> 3)","type":"skill","skill":"ranged","ring":"void","at_rank":2,"xp":6,"in_curriculum":true}],"techniques":[{"name":"Skulk","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ninjutsu","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Shinobi are known for walking silently from shadow to shadow, moving like phantoms. Some of this relies upon agility and speed, of course, but veterans in the art of stealth know that using a crowd or another visual distraction to walk unnoticed can be as effective as the most complex acrobatics.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform an Initiative or Attack check using Air, you may spend (op) as follows:</span></p><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If you are in Obscuring terrain, a crowd, or otherwise concealed from sight, one character with vigilance lower than or equal to your ranks in Skulduggery loses sight of you.</span></p>","source":{"book":"core_rulebook","page":226},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.tKw2dMxzwVBuWOaT"},{"name":"Striking as Air","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Not every stroke a warrior throws in battle is intended to kill—even if they all lead to that end goal. A skilled fighter can tell when an attack will not land and subtly shift it into a different sort of attack, meant to probe the enemy’s defenses or draw their guard out of position. By carefully placing attack after attack, a master of the blade can eventually whittle down their opponent’s options until none remain but death.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (Air) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(air)(op)+: </span><span class=\"fontstyle3\">Reserve one of your rolled dice, plus one additional die per (op)(op) spent this way. These dice become dropped dice. When making a check with the same skill before the end of your next turn, you may roll one fewer (ring) per reserved (ring) and one fewer (skill) per reserved (skill), then add the reserved dice to your roll. These dice count as rolled dice, but are added set to the results they had when they were reserved.</span></p>","source":{"book":"core_rulebook","page":177},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.pNvLI7ImoPeZPzwK"},{"name":"Explosive Arrival","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">After you perform an Attack action against a target who is Dazed or unaware of your presence, that target receives strife equal to your school rank. If your target is an enemy leader’s cohort in a mass battle, the enemy army also receives that much panic</span>.</p>","source":{"book":"fields_of_victory","page":74},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.bCg2D67yA5yoON9g"},{"name":"Swift Scouting","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ninjutsu","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The line between a shinobi and a scout is mostly one of their current assignment. Yet, while traditional scouting can take days or weeks, sufficiently experienced survivalists who have lived in the wilds can undertake scouting missions much more quickly than typical observers. Shinobi must often spend long periods of time traveling Rokugan, hiding in the wilderness, or spying on targets on the road. As a result, many are intimately familiar with the sorts of environments found in those types of locations and can quickly sweep an area to identify the points of interest inside it. Especially skilled shinobi are likely to leave traps behind for enemy scouts or forces in the area.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, or once per scene as a Movement and Support action, you may make a </span><span class=\"fontstyle2\">TN 3 Survival (water) check </span><span class=\"fontstyle3\">to scout the terrain around you. If you activate this technique in an urban environment or on the ocean, use Skulduggery or Seafaring instead, respectively.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you discover all terrain qualities of the area around you (several miles in all direction during downtime, or the entire area in which the scene is occurring), as well as any fortifications in the area. Characters with vigilance lower than your Air Ring plus your bonus successes do not detect you during this time.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(water)(op)(op) </span><span class=\"fontstyle2\">(<em>Downtime</em> or <em>Mass Battle</em>): </span><span class=\"fontstyle3\">If you succeed, you may choose one part of the area (a single battle zone, if using the rules for battle zones) and add one of the following terrain qualities to that area: Confining, Dangerous, Entangling, Obscuring.</span></p><p><span class=\"fontstyle2\">(water)(op)(op) (<em>Other Scene</em>): </span><span class=\"fontstyle3\">If you succeed, you may choose a position in the area you scouted. Up to three range bands surrounding that position gain one of the following terrain qualities: Confining, Dangerous, Entangling, Obscuring.</span></p><p><span class=\"fontstyle5\">(water)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">You discover the location and composition of any enemy forces in the area led by characters with Air Ring lower than your vigilance plus (op) spent this way.</span></p><p><span class=\"fontstyle5\">(water)(op)(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">During your next turn, if you perform an action targeting an enemy cohort, ignore any fortification it is occupying. You may resolve effects as if you were inside that fortification.</span></p>","source":{"book":"fields_of_victory","page":105},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.JuuH6W9ZSSNnnyYq","skill":"survival"},{"name":"Trip the Leg","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The bushi’s spear flashes out, aiming low to trip up their opponent and send the unlucky foe crashing to the ground.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action using one readied polearm, you may make a </span><span class=\"fontstyle2\">TN 2 Martial Arts [Melee] check </span><span class=\"fontstyle3\">targeting one character at range 1–2.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Prone condition.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you succeed, the target receives 2 fatigue and 2 strife.</span></p><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">If your target’s vigilance is lower than or equal to </span><span class=\"fontstyle5\">(op) </span><span class=\"fontstyle3\">spent this way, they suffer the Disoriented condition.</span></p>","source":{"book":"court_of_stones","page":113},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.wJuo5wuCSga4kIc2","skill":"melee"},{"name":"Cautious Tread","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Horses and camels are excellent mounts, but their long legs make them somewhat more vulnerable to certain kinds of terrain than their human riders. A skillful handler knows how to lead their mount around the most dangerous spots, whether holes dug by rodents in the plains, swampy terrain, or chasms in the desert.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Movement action check while riding a mount, you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(op)(op): </span><span class=\"fontstyle3\">Choose one of the following terrain qualities: Dangerous, Entangling, or Obscuring. You and your mount ignore its effects. This effect persists until the end of your next turn.</span></p>","source":{"book":"children_of_the_five_winds","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.O8sn8QkmCqKqBe6G"},{"name":"Employ Terrible Thunder","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"ninjutsu","rank":2,"description":"<p><span class=\"fontstyle0\"><em>For some samurai, there is something they prize above honor: victory. For them, honor is meaningless if their lord is dead or their family lost. Any method that achieves victory is worthy, even if the Emperor themselves has outlawed it.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Movement and Support action, you may make a </span><span class=\"fontstyle2\">TN 4 Skulduggery check </span><span class=\"fontstyle3\">and expend 1 charge of blasting powder (see page 90) to place it in your environment at a target position at range 0–1 of you. You must forfeit honor equal to equal to half your honor rank (rounded up) to use this technique.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you set the blasting powder to explode at the end of the next round. Some or all of the following occur based on the scene type:</span></p><ul><li><p><span class=\"fontstyle3\">- (<em>Mass Battle</em>) Any nearby cohort (such as those in the same zone, if using the rules for zones on page 118) is caught by the blast, and that army receives 5 attrition and 5 panic, plus 1 per bonus success.</span></p></li><li><p><span class=\"fontstyle3\">- (<em>Mass Battle</em>) If you placed the blasting powder inside of a fortification (see the </span><span class=\"fontstyle2\">Fortifications </span><span class=\"fontstyle3\">sidebar on page 276 of the core rulebook), reduce its difficulty value by 1, plus 1 per bonus success.</span></p></li><li><p><span class=\"fontstyle3\">- (<em>Mass Battle</em>) One cohort leader affected by the explosion suffers the Immobilized and Lightly Wounded conditions.</span></p></li><li><p><span class=\"fontstyle3\">- (<em>Other Scene</em>) Each character at range 0–2 of the target position suffers 10 physical damage plus 1 per bonus success, suffers the Dazed condition, and receives 5 strife.</span></p></li><li><p><span class=\"fontstyle3\">- (<em>Other Scene</em>) Items at range 0–2 of the target position gain the Damaged item quality.</span></p></li><li><p><span class=\"fontstyle3\">- (<em>Other Scene</em>) Any structure (such as a bridge, house, or wall) at range 0–1 of the target position gains the Damaged quality.</span></p></li></ul><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle6\">(op)</span><span class=\"fontstyle2\" style=\"color:rgb(0,0,0);\">: </span><span class=\"fontstyle3\">Any item or structure damaged by this effect gains the Destroyed quality instead.</span></p><p><span class=\"fontstyle2\" style=\"color:rgb(0,0,0);\">(op)(op): </span><span class=\"fontstyle3\">The area at range 0–2 of the position of the explosion gains the Dangerous and Obscuring terrain qualities, and flammable objects in the area are set ablaze.</span></p><p><span class=\"fontstyle2\">(op)+: </span><span class=\"fontstyle3\">The blasting powder does not detonate for one additional round per (op) spent this way.</span></p>","source":{"book":"fields_of_victory","page":105},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.ek7B6RF2KoXowmIU","skill":"skulduggery"},{"name":"Staggering Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Putting an arrow at a foe’s feet can cause them to stumble or trip, and an experienced archer knows how to take full advantage of this, planting bolts to break an</em></span><em> </em><span class=\"fontstyle0\"><em>enemy’s stride or pinning their clothes to slow them down, making any approach extremely treacherous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Martial Arts [Ranged] check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (fire)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Dangerous quality. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(air) or (water)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Entangling quality. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.6N5n9fweaz1CbLCu"},{"name":"The Patient Viper","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"ninjutsu","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Sometimes, the best way to approach a target is to stand still. Shinobi often lie in wait for hours or even days, patiently maintaining their position to ensure that they strike well when their foe arrives.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, you may make a </span><span class=\"fontstyle2\">TN 4 Fitness (earth) check </span><span class=\"fontstyle3\">targeting your cohort </span><span class=\"fontstyle3\" style=\"color:rgb(0,0,0);\">(if you are currently the leader of a cohort) </span><span class=\"fontstyle3\">or yourself and a number of other characters up to your ranks in Command (in any other scene) who are within Dangerous, Entangling, or Obscuring terrain.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, all targets become hidden and are not noticed by characters with vigilance lower than or equal to your Earth Ring plus your bonus successes. These hidden characters cannot be the target of Attack actions. This effect persists until the end of your next turn, or until any target you have hidden performs an Attack or Movement action.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(earth)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">This effect persists for one additional round per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(earth)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Reduce the TN of the first Attack action check one of your targets makes against another character in the terrain in which your forces are hidden by 1 per (op) spent this way.</span></p>","source":{"book":"fields_of_victory","page":106},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-ninjitsu-l5r-sortilege.Item.fjq7mXymhQT93tSi","skill":"fitness"},{"name":"Ender of Works","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When a fortification’s difficulty value would be reduced during a mass battle, the value is lowered by that amount plus your ranks in Labor instead. If there is a cohort occupying it, that cohort’s army suffers panic equal to your ranks in Skulduggery.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.jUP259fL2ojZcSye"}],"peculiarities":[{"name":"Famously Reliable","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"earth","types":"Fame, Interpersonal","description":"<p><span class=\"fontstyle0\"><em>When the lord came to see how the smith was proceeding on his sword, he found the smithy a shambles, the river running through the forge, and the smith with his robes tied up around his middle.</em></span></p><p><span class=\"fontstyle0\"><em>“Tsi-san,” said the great lord. “I trust my sword will be ready tomorrow, as we agreed?”</em></span></p><p><span class=\"fontstyle0\"><em>“Of course, great lord,” said the smith, bowing low. “This is only a minor setback.”</em></span></p><p><span class=\"fontstyle2\"><em>– The Trials of Tsi Wenfu, </em></span><span class=\"fontstyle3\"><em>author unknown</em></span></p><p></p><p><span class=\"fontstyle2\">The following apply to a character with the Famously Reliable distinction:</span></p><ul><li><p><span class=\"fontstyle2\">- Other people have heard of you for your remarkable adherence to your oaths and responsibilities, even over and above most samurai, and they believe it by default unless given evidence to the contrary.</span></p></li><li><p><span class=\"fontstyle2\">- When performing a check for which you need to leverage your reputation for keeping your oaths and bargains (such as a Command (earth) check to calm a panicked soldier or a Performance (earth) check to relate a tale that inspires patience), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":104},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.DWrZtBuyK83Ah3a7"},{"name":"Maimed Arm","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"fire","types":"Physical, Scar","description":"<p><em>The samurai kept her arm tucked in her kimono. Her left sleeve flapped empty in the breeze, a testament to her folly—and resilience.</em></p><p></p><p>The following apply to a character with the Maimed Arm adversity:</p><ul><li><p>- Your right or left arm is injured (your choice at the time the disadvantage is assigned), making it much harder to perform activities that involve use of that arm. You can use the arm, but gripping anything tightly causes you pain, and you might need a sling to help the arm heal properly.</p></li><li><p>-  When you make a check for which you need to use two hands at once (such as a Design (fire) check to sew a new kimono or a Martial Arts (melee) (fire) check to overwhelm a foe with a powerful overhead slice), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":125},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.BUdmYV82FFppmXo1"},{"name":"Kintsugi","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"earth","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>Mirumoto Kinshichirō did not cry then. As a child, he carelessly dropped this bowl, one that had been in his family for generations, a gift supposedly blessed by the actual Kami Togashi. His parents berated him, and he carried the guilt all throughout his adolescence. He even decided to study with the Agasha mystics, but his parents cared so little, they let him leave.</em></span></p><p><span class=\"fontstyle0\"><em>They did not realize that hidden in his belongings, a box contained the pieces of the bowl, carefully wrapped in a cloth. This box remined by his side as he studied, until Kinshichirō had to make his masterpiece. The bowl had broken into seven pieces, exactly the number of his siblings plus him, yet when he unfolded the cloth, he noted he only had six. The despair he felt only lasted for a little while.</em></span></p><p><span class=\"fontstyle0\"><em>When Kinshichirō returned home, he unveiled the bowl. He had joined the cracks with gold, and the missing space filled with a singular piece of jade with the family mon. His siblings welcomed him back, so he finally allowed the tears to flow.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Kintsugi passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You have a particular fondness and skill for kintsugi, the art of mending broken pottery with gold or other similar substances.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to mend an object with kintsugi or interact with a piece of kintsugi-repaired pottery (such as a Culture (earth) check to recall the name of a particular practitioner of kintsugi by their artist’s mark on a piece of pottery or a Labor (earth) check to produce a breathtaking piece), you remove 3 strife.</span></p></li></ul>","source":{"book":"writ_of_the_wild","page":104},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.pVo3SUK4ZeNQUwye"},{"name":"Eyes of Many","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"air","types":"Mental","description":"<p><em>“If you live worrying about the eyes and thoughts of others, your life is no longer your own.”</em></p><p><em>– Youta, Mystic of the Mountain</em></p><p><strong>Effects:</strong> The following apply to a character with the Eyes of Many anxiety:</p><ul><li><p>-  You are constantly worried that others are watching and judging you, whether maliciously or not. You are unable to relax in crowded places, and you tend to worry about your impressions on strangers more than most other people would.</p></li><li><p>- After performing a check in a crowded place or where two or more strangers are actively listening to you (such as a Courtesy (air) check to tell your employer your mission went very well when it did not in front of their other retainers or a Fitness (air) check to avoid notice), you suffer 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":73},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.Sw9LFYlxdkwGFCfu"},{"name":"Bitter Betrothal","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Interpersonal","description":"<p><em>“My husband returns home tonight,” she said in a low whisper, passing the bag of coins beneath the table to the men seated across from her. Nobody in this inn knew her face, yet she still felt the need for caution. </em></p><p><em>“He will be traveling via the eastern road.”</em></p><p><em>“It shall be done,” said the leader. Without further word, he and his companions rose from the table and left the inn. The room seemed somehow lighter without them in it. Soon, she would be rid of him.</em></p><p></p><p>The following apply to a character with the Bitter Betrothal adversity</p><ul><li><p>- Something significantly complicates your relationship with your betrothed or spouse. As a result, they often undermine your efforts, whether out of malice, negligence, or an incompatible set of goals.</p></li><li><p>- When you make a check that requires the collaboration of your betrothed or spouse (such as a Courtesy (water) check to make a polite request to their family for political backing or a Culture (water) check to know the proper thing to do at a social function involving their relatives), you must choose and reroll two dice containing (su) or (ex). After resolving the check, if you failed, you gain 1 Void point.</p></li></ul><p></p>","source":{"book":"core_rulebook","page":117},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.p1cGWR2i5WrGtIKb"}],"titles":[{"name":"Master Saboteur","xp_used":40,"xp_cost":40,"in_curriculum":false,"bought_at_rank":3,"description":"<p><span class=\"fontstyle0\">Akodo wrote that destroying fortifications mostly serves the satisfaction of generals who have had to besiege them, for earthworks should, when possible, be captured intact. However, the Kami of warfare knew the value of disabling key defenses to make fortresses indefensible, and wrote extensively of the use of sappers. To this day in Rokugan, sappers remain a critical part of most battles near fortifications, for an extended siege can easily ruin an entire campaign. Each generation of saboteurs trains the next, and only once a trainee has proven themselves in front of a number of their mentors are they accepted as a peer.</span></p><p><span class=\"fontstyle2\"><strong>Assigned by:</strong> </span><span class=\"fontstyle0\">Three other master saboteurs, who are usually members of a general’s command staff or found leading specialized clandestine units.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">None</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Ender of Works</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Trade Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Government</p></td><td><p>Skill</p></td></tr><tr><td><p>Martial Arts [Unarmed]</p></td><td><p>Skill</p></td></tr><tr><td><p>Medicine</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-ninjutsu\">(ninjutsu) Rank 1-2 Ninjutsu</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-rituals.Item.L5RCoreRit000030\" data-pack=\"l5r5e.core-techniques-rituals\" data-type=\"Item\" data-id=\"L5RCoreRit000030\">(ritual) Imbue Thunder</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-ninjutsu.Item.L5RCoreNin000018\" data-pack=\"l5r5e.core-techniques-ninjutsu\" data-type=\"Item\" data-id=\"L5RCoreNin000018\">(ninjutsu) Wreak Havoc</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"fields_of_victory","page":134},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.yzpY08fb3yQ3IcO9"}],"bonds":[],"gear":[{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Shuriken","quantity":6,"description":"<p><span class=\"fontstyle0\">Favored by shinobi, shuriken are small metal discs with a sharpened edge that come in a dizzying array of sizes and styles. They are designed mainly to distract, but shuriken can also be coated with toxins for lethality, and any cutting edge can kill if used properly.</span></p>","source":{"book":"core_rulebook","page":237},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.5Lr1CNs1uvX7J38y","damage":2,"deadliness":4,"range":"0","grip_1":"(stab or slash): -, (thrown): Martial Arts [Ranged], Range 1-3","grip_2":"N/A","skill":"unarmed","category":"Specialist Weapons","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000005","name":"Concealable"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Common Clothes","quantity":1,"description":"<p>Rokugani clothing runs the gamut from the simple trousers and smocks worn by peasants, to the broad-shouldered haori worn by traditionalist samurai, to the noble’s embroidered silk kimono.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.vYOT19tl8uiIDt14","armor":{"physical":1,"supernatural":0},"rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Engineer's Kit","quantity":1,"description":"<p>These kits provide an architect, civil engineer, siege engineer, or builder with a set of basic tools for surveying and building. These tool kits typically include measuring and surveying tools, rolls of parchment for making plans, various drafting implements, and an assortment of carpenters’ and masons’ tools. (Cost: 3 bu. Rarity: 3.)</p>","source":{"book":"shadowlands","page":107},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.xFAWMoykfSYWIScE","rarity":"3","zeni":"3 bu"},{"name":"Jade Medallion","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"4","zeni":"0","properties":[]}]}]};
